"""Demo 1: Base vs two-deletion Seidel energy for a single K_{m,n}.

Builds the Seidel matrix S = J - I - 2A, deletes two independent cross edges,
and compares the numeric energy with the closed forms 2(m+n-1) and
(m+n)+sqrt((m+n+2)^2-32)."""
from __future__ import annotations
import math
import numpy as np

def seidel_kmn(m: int, n: int) -> np.ndarray:
    N = m + n
    A = np.zeros((N, N))
    for i in range(m):
        for j in range(m, N):
            A[i, j] = A[j, i] = 1.0
    return np.ones((N, N)) - np.eye(N) - 2.0 * A

def energy(S: np.ndarray) -> float:
    return float(np.abs(np.linalg.eigvalsh(S)).sum())

def compare(m: int, n: int) -> None:
    S = seidel_kmn(m, n)
    base = energy(S)
    S[0, m] += 2.0; S[m, 0] += 2.0          # delete {0, m}
    S[1, m + 1] += 2.0; S[m + 1, 1] += 2.0  # delete {1, m+1}
    two = energy(S)
    N = m + n
    print(f"K_{{{m},{n}}}: base={base:.5f} (=2(N-1)={2*(N-1)}), "
          f"two-del={two:.5f} (=N+sqrt((N+2)^2-32)={N+math.sqrt((N+2)**2-32):.5f}), "
          f"increase={two>base}")

if __name__ == "__main__":
    for (m, n) in [(2, 3), (3, 3), (4, 6), (7, 7)]:
        compare(m, n)

"""Demo 2: Sweep verifying the main theorem (strict increase, no threshold).

For every admissible (m,n) with m,n>=2 and m+n>=5, the two-deletion energy
(m+n)+sqrt((m+n+2)^2-32) strictly exceeds the base energy 2(m+n-1)."""
from __future__ import annotations
import math
from typing import Tuple

def base_energy(m: int, n: int) -> float:
    return 2.0 * (m + n - 1)

def two_deletion_energy(m: int, n: int) -> float:
    N = m + n
    return N + math.sqrt((N + 2) ** 2 - 32)

def admissible(m: int, n: int) -> bool:
    return m >= 2 and n >= 2 and m + n >= 5

def sweep(hi: int = 12) -> bool:
    ok = True
    for m in range(2, hi):
        for n in range(2, hi):
            if not admissible(m, n):
                continue
            b, t = base_energy(m, n), two_deletion_energy(m, n)
            if not t > b:
                ok = False
                print(f"COUNTEREXAMPLE at ({m},{n}): base={b}, two={t}")
    return ok

if __name__ == "__main__":
    print("main theorem holds on all admissible (m,n) up to 11:", sweep())

"""Demo 4: The general k-matching conjecture.

Deleting a matching of size k (k pairwise vertex-disjoint cross edges) from
K_{m,n} is conjectured to give Seidel energy (N+2k-4)+sqrt((N+2)^2-16k), N=m+n,
valid for N>=2k+1. This checks the formula numerically for several k."""
from __future__ import annotations
import math
import numpy as np

def seidel_matching_deleted(m: int, n: int, k: int) -> np.ndarray:
    N = m + n
    A = np.zeros((N, N))
    for i in range(m):
        for j in range(m, N):
            A[i, j] = A[j, i] = 1.0
    S = np.ones((N, N)) - np.eye(N) - 2.0 * A
    for t in range(k):                       # matching {t, m+t}
        S[t, m + t] += 2.0; S[m + t, t] += 2.0
    return S

def energy(S: np.ndarray) -> float:
    return float(np.abs(np.linalg.eigvalsh(S)).sum())

def formula(m: int, n: int, k: int) -> float:
    N = m + n
    return (N + 2 * k - 4) + math.sqrt((N + 2) ** 2 - 16 * k)

if __name__ == "__main__":
    m, n = 7, 8
    for k in range(1, min(m, n) + 1):
        if m + n < 2 * k + 1:
            continue
        num = energy(seidel_matching_deleted(m, n, k))
        fml = formula(m, n, k)
        print(f"k={k}: numeric={num:.6f} formula={fml:.6f} "
              f"match={abs(num - fml) < 1e-6}")

