function SeidelEnergy(m, n, deleted):
    N <- m + n
    A <- zero N x N matrix
    for i in 0..m-1, j in m..N-1: A[i,j] <- A[j,i] <- 1
    S <- J(N) - I(N) - 2A            # J all-ones, I identity
    for (a, b) in deleted:
        u <- a; v <- m + b
        S[u,v] <- S[u,v] + 2; S[v,u] <- S[v,u] + 2
    lambda <- eigenvalues(S)         # symmetric eigensolver
    return sum(|lambda_i|)

