from __future__ import annotations
import numpy as np

def seidel_matrix(m: int, n: int, deleted: list[tuple[int, int]] | None = None) -> np.ndarray:
    """Seidel matrix S = J - I - 2A of K_{m,n} with an optional list of deleted
    cross edges given as (left_index, right_offset) with 0<=left<m, 0<=off<n."""
    N = m + n
    A = np.zeros((N, N))
    for i in range(m):
        for j in range(m, N):
            A[i, j] = A[j, i] = 1.0
    S = np.ones((N, N)) - np.eye(N) - 2.0 * A
    for (a, b) in (deleted or []):
        u, v = a, m + b
        S[u, v] += 2.0
        S[v, u] += 2.0
    return S

def seidel_energy(S: np.ndarray) -> float:
    """Sum of absolute values of the eigenvalues of the symmetric matrix S."""
    return float(np.abs(np.linalg.eigvalsh(S)).sum())

from __future__ import annotations
import math

def base_energy(m: int, n: int) -> float:
    """Closed-form Seidel energy of K_{m,n}: 2(m+n-1)."""
    return 2.0 * (m + n - 1)

def two_deletion_energy(m: int, n: int) -> float:
    """Closed-form Seidel energy after deleting two independent edges."""
    N = m + n
    return N + math.sqrt((N + 2) ** 2 - 32)

def energy_increases(m: int, n: int) -> bool:
    """Decide the main theorem for a pair (m,n): strict increase iff m,n>=2 and
    m+n>=5 (no threshold obstruction)."""
    if m < 2 or n < 2 or m + n < 5:
        return False
    return two_deletion_energy(m, n) > base_energy(m, n)
